class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0, which is (0, 0)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final coordinates back to position
        # Position = row * n + col
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        winners = 0

        # For each player from 0 to n-1
        for player in range(n):
            # Count how many balls of each color this player picked
            color_count = {}
            for x, y in pick:
                if x == player:  # Only consider picks by current player
                    color_count[y] = color_count.get(y, 0) + 1

            # Find the maximum count of any single color
            max_count = max(color_count.values()) if color_count else 0

            # Player i wins if they have at least (i+1) balls of same color
            if max_count >= player + 1:
                winners += 1

        return winners

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate minimum flips needed to make all rows palindromic
        row_flips = 0
        for i in range(m):
            for j in range(n // 2):
                # For symmetric positions in row i
                if grid[i][j] != grid[i][n - 1 - j]:
                    row_flips += 1

        # Calculate minimum flips needed to make all columns palindromic
        col_flips = 0
        for j in range(n):
            for i in range(m // 2):
                # For symmetric positions in column j
                if grid[i][j] != grid[m - 1 - i][j]:
                    col_flips += 1

        # Return the minimum of row flips and column flips
        return min(row_flips, col_flips)

